// Dipanggil backend lewat fallback getNodeRedClassEndpointUrl():
// POST http://<NODERED_BASE_URL>/api/<classKey>  { state, unit? }
// classKey datang dari URL path (:classKey). ROOM_TO_UG menentukan UG65
// mana yang menangani ruangan itu -- satu-satunya tempat yang perlu
// diedit kalau ada ruangan baru.
var ROOM_TO_UG = {
    "c140402": "LT4",
    "c140405": "LT4",
    "c140408": "LT4",
    "c140409": "LT4",
    "c140203": "LT2"
};

var classKey = String((msg.req && msg.req.params && msg.req.params.classKey) || "").toLowerCase();
var body = msg.payload || {};
var state = String(body.state || "").toLowerCase();
var unit = body.unit; // mis. "WS523_A", "WS502_B" -- kosong = semua unit ruangan itu
var ug = ROOM_TO_UG[classKey];

// PENTING: pakai `msg` ASLI (bukan objek baru) untuk balasan http response --
// msg.req/msg.res/msg._msgid yang dilekatkan node "http in" cuma ada di msg
// ini. Kalau diganti objek baru, node "http response" tidak tahu koneksi
// mana yang harus dibalas dan client akan menggantung sampai timeout.
if (!classKey || !ug || ["on", "off"].indexOf(state) === -1) {
    msg.statusCode = 400;
    msg.payload = { success: false, message: "classKey/state tidak valid atau ruangan tidak dikenal: " + JSON.stringify(body) };
    return [null, msg];
}

var routeMsg = {
    topic: ug,
    payload: JSON.stringify({ classKey: classKey, state: state, unit: unit, source: body.source || "web_api" }) + "\n"
};
msg.statusCode = 200;
msg.payload = { success: true, message: "Perintah " + state.toUpperCase() + " diteruskan ke " + ug + " (" + classKey + (unit ? ", unit " + unit : "") + ")" };
return [routeMsg, msg];

// UG65 tidak bisa HTTP -- kirim {method, url, payload} lewat TCP ke sini,
// Mini PC yang benar-benar memanggil Web (backend lokal :5001).
// X-Tenant WAJIB disertakan -- tanpa ini resolveTenant() di backend
// jatuh ke DEFAULT_TENANT (fakultas lain di .env) dan device/class FMIPA
// tidak ketemu ("Device not found") walau request-nya sendiri sukses.
var p = msg.payload || {};
if (!p.method || !p.url) {
    node.warn("Payload telemetri tidak valid: " + JSON.stringify(p));
    return null;
}
msg.method = p.method;
msg.url = p.url;
msg.payload = p.payload;
msg.headers = { "content-type": "application/json", "x-tenant": "fmipa" };
return msg;

// Web API sesekali sempat tidak terjangkau sesaat. Coba lagi otomatis
// (maks 3x, jeda 2 detik) sebelum menyerah diam-diam.
msg._retryCount = (msg._retryCount || 0) + 1;
if (msg._retryCount > 3) {
    node.warn("Web API tidak terjangkau setelah 3x percobaan (control-hub): " + (msg.error && msg.error.message));
    return null;
}
return msg;
